INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4110453', 'Capture of Malacca', 'The governor of Portuguese India Afonso de Albuquerque conquered the city of Malacca in 1511. The port city of Malacca controlled the narrow, strategic Strait of Malacca, through which all seagoing trade between China and India was concentrated.', 1511, 7, 25, 1511, 8, 15, 'day', '25 July 1511 – 15 August 1511', 52, 'https://en.wikipedia.org/wiki/Capture_of_Malacca_(1511)'),
  ('Q4273940', 'Siege of Malacca', 'The siege of Malacca occurred in 1568, when the Sultan of Aceh Alauddin attacked the Portuguese-held city of Malacca. The city had been held by the Portuguese since its capture by Afonso de Albuquerque in 1511.', 1568, NULL, NULL, NULL, NULL, NULL, 'year', '1568', 47, 'https://en.wikipedia.org/wiki/Siege_of_Malacca_(1568)'),
  ('Q55633157', 'Siege of Johor', 'The siege of Johor of 1587 was a military operation in which Portuguese forces successfully sieged, sacked, and razed Johor, capital of its eponymous sultanate. The city would later be rebuilt at a different location.', 1587, 7, NULL, 1587, 8, NULL, 'month', 'July 1587 – August 1587', 34, 'https://en.wikipedia.org/wiki/Siege_of_Johor_(1587)'),
  ('Q7510222', 'Siege of Malacca', 'The siege of Malacca of 1606 was a military engagement between a Dutch force commanded by Cornelis Matelief and the Portuguese commander André Furtado de Mendonça. The small Portuguese garrison managed to hold out and stop any Dutch direct attacks on the city until additional reinforcements led by Martim Afonso de Castro arrived, which caused the Dutch to retreat from the siege.', 1606, NULL, NULL, 1606, 8, 17, 'year', '1606', 41, 'https://en.wikipedia.org/wiki/Siege_of_Malacca_(1606)'),
  ('Q4337398', 'Siege of Malacca', 'The siege of Malacca (3 August 1640 – 14 January 1641) was initiated by the Dutch East India Company and their local ally, Johor, against Portuguese Malacca. It ended with a Portuguese surrender and, according to Portugal, the deaths of thousands of Portuguese individuals.', 1640, 8, 3, 1641, 1, 14, 'day', '3 August 1640 – 14 January 1641', 43, 'https://en.wikipedia.org/wiki/Siege_of_Malacca_(1640%E2%80%931641)'),
  ('Q4204647', '1833 Sumatra earthquake', 'The 1833 Sumatra earthquake occurred on November 25 at about 22:00 local time, with an estimated magnitude in the range of 8.8–9.2 Mw. It caused a large tsunami that flooded the southwestern coast of the island.', 1833, NULL, NULL, NULL, NULL, NULL, 'year', '1833', 41, 'https://en.wikipedia.org/wiki/1833_Sumatra_earthquake'),
  ('Q7166879', 'Perak War', 'The Perak War (1875–1877) took place between British and local forces in Perak, a state in northwestern Malaysia. The sultan of Lower Perak and other local chiefs attempted to end foreign influence in the region and remove the British administrator James W. W. Birch.', 1875, NULL, NULL, 1876, NULL, NULL, 'year', '1875–1876', 30, 'https://en.wikipedia.org/wiki/Perak_War'),
  ('Q6177105', 'Jementah Civil War', 'The Jementah Civil War broke out in 1879 in Jementah in northern Johor when Tengku Alam Shah, the heir of late Sultan Ali of the autonomous principality of Muar refused to surrender the principality to the central administration of Abu Bakar, the then Maharaja of Johor. The aftermath of the conflict led to the consolidation of Johor''s rules over Muar territory again and the opening of Muar town by Sultan Abu Bakar as the first sultan of modern Johor.', 1879, 12, 30, 1879, 12, 30, 'day', '30 December 1879', 26, 'https://en.wikipedia.org/wiki/Jementah_Civil_War'),
  ('Q1908014', 'Mat Salleh Rebellion', 'The Mat Salleh Rebellion was a series of major armed disturbances against the British North Borneo Chartered Company administration in North Borneo, now the Malaysian state of Sabah. It was instigated by Datu Muhammad Salleh (also known as Mat Salleh), a local chief from the Lingkabo district and Sugut River.', 1894, NULL, NULL, 1905, NULL, NULL, 'year', '1894–1905', 37, 'https://en.wikipedia.org/wiki/Mat_Salleh_Rebellion'),
  ('Q4871375', 'Battle of Kampar', 'The Battle of Kampar (30 December 1941 – 2 January 1942) was an engagement of the Malayan Campaign during World War II, involving British and Indian troops from the 11th Indian Infantry Division and the Japanese 5th Division. On 27 December, in an effort to prevent the capture of RAF Kuala Lumpur, the 11th Indian Infantry Division occupied Kampar, which offered a strong natural defensive position.', 1941, 12, 30, 1942, 1, 2, 'day', '30 December 1941 – 2 January 1942', 41, 'https://en.wikipedia.org/wiki/Battle_of_Kampar'),
  ('Q4871087', 'Battle of Gemas', 'The Battle of Gemas—part of the wider Battle of Muar—took place during the Japanese invasion of Malaya in the Pacific Campaign of the Second World War. The action occurred on 14 January 1942 at the Gemencheh Bridge near Gemas and saw almost 800 troops of the Japanese 5th Division killed, wounded or missing during a fierce ambush initiated by Australian soldiers from 2/30th Battalion, assigned to the 27th Brigade of the 8th Division.', 1942, 1, 14, NULL, NULL, NULL, 'day', '14 January 1942', 39, 'https://en.wikipedia.org/wiki/Battle_of_Gemas'),
  ('Q1934591', 'Battle of North Borneo', 'The Battle of North Borneo took place during the Second World War between Allied and Japanese forces. Part of the wider Borneo campaign of the Pacific War, it was fought between 10 June and 15 August 1945 in North Borneo (later known as Sabah).', 1945, 6, 10, 1945, 8, 15, 'day', '10 June 1945 – 15 August 1945', 51, 'https://en.wikipedia.org/wiki/Battle_of_North_Borneo'),
  ('Q18920234', 'Battle of Labuan', 'The Battle of Labuan was an engagement fought between Allied and Imperial Japanese forces on the island of Labuan off Borneo during June 1945. It formed part of the Australian invasion of North Borneo, and was initiated by the Allied forces as part of a plan to capture the Brunei Bay area and develop it into a base to support future offensives.', 1945, 6, 10, 1945, 6, 21, 'day', '10 June 1945 – 21 June 1945', 48, 'https://en.wikipedia.org/wiki/Battle_of_Labuan'),
  ('Q2354629', 'Malayan Emergency', 'The Malayan Emergency, also known as the Anti–British National Liberation War, (1948–1960) was a guerrilla war fought in Malaya between communist pro-independence fighters of the Malayan National Liberation Army (MNLA) and the military forces of the Federation of Malaya and the Commonwealth (British Empire). The MNLA fought to win Malayan independence from the British Empire and to establish a communist state, while the Malayan Federation and Commonwealth forces fought to protect British economic and colonial interests and combat communism.', 1948, 6, 16, 1960, 7, 12, 'day', '16 June 1948 – 12 July 1960', 68, 'https://en.wikipedia.org/wiki/Malayan_Emergency'),
  ('Q4262005', 'Bukit Kepong Incident', 'The Bukit Kepong incident (Malay: Peristiwa Bukit Kepong) was an armed encounter in 1950 during the Malayan Emergency between the Federation of Malaya Police and the guerrillas of the Malayan National Liberation Army (MNLA), the paramilitary wing of the Malayan Communist Party (MCP). This conflict took place in an area surrounding the Bukit Kepong police station in Bukit Kepong, about 59 kilometres (37 mi) from Muar town, Johor.', 1950, 2, 23, NULL, NULL, NULL, 'day', '23 February 1950', 34, 'https://en.wikipedia.org/wiki/Bukit_Kepong_incident'),
  ('Q17017491', 'communist insurgency in Sarawak', 'The communist insurgency in Sarawak was an insurgency in Malaysia from 1962 to 1990, and involved the North Kalimantan Communist Party (NKCP) and the Malaysian Government. It was one of the two communist insurgencies to challenge the former British colony of Malaysia during the Cold War.', 1962, 6, 22, 1990, 11, 3, 'day', '22 June 1962 – 3 November 1990', 45, 'https://en.wikipedia.org/wiki/Communist_insurgency_in_Sarawak'),
  ('Q18711630', 'cross border attacks in Sabah', 'The cross border attacks in Sabah are a series of cross border terrorist attacks perpetrated by Moro pirates from Mindanao, Philippines, in the state of Sabah, Malaysia, that began even before the British colonial period. Many civilians have died or suffered during these incidents, causing an increase in anti-Filipino sentiment among the native peoples of Sabah, especially after major attacks in 1985, 2000 and 2013.', 1962, NULL, NULL, NULL, NULL, NULL, 'year', '1962', 48, 'https://en.wikipedia.org/wiki/Cross_border_attacks_in_Sabah'),
  ('Q1361929', 'Indonesia–Malaysia confrontation', 'The Konfrontasi, also known as the Indonesia–Malaysia confrontation or Borneo confrontation, was an armed conflict from 1963 to 1966 that stemmed from Indonesia''s opposition to the creation of the state of Malaysia. Vital precursors to the conflict included Indonesia''s policy of confrontation against Dutch New Guinea from March to August 1962 and the Indonesia-backed Brunei revolt in December 1962.', 1963, 1, 20, 1966, 8, 11, 'day', '20 January 1963 – 11 August 1966', 64, 'https://en.wikipedia.org/wiki/Konfrontasi'),
  ('Q15991222', 'Independence of Singapore Agreement 1965', 'The Independence of Singapore Agreement 1965 was a pivotal agreement concluded between the governments of Malaysia and Singapore on 7 August 1965. It provided the legal and constitutional framework for Singapore''s formal secession from Malaysia, wherein it ceased to be a constituent state and assumed the status of an independent and sovereign nation.', 1965, 8, 7, NULL, NULL, NULL, 'day', '7 August 1965', 48, 'https://en.wikipedia.org/wiki/Independence_of_Singapore_Agreement_1965'),
  ('Q4574541', '1971 Kuala Lumpur floods', 'The 1971 Kuala Lumpur floods was a major flash flood disaster in Malaysia that occurred in January 1971. The flooding was the result of heavy monsoon rains, which swelled the Klang, Batu, and Gombak rivers.', 1971, 1, NULL, NULL, NULL, NULL, 'month', 'January 1971', 37, 'https://en.wikipedia.org/wiki/1971_Kuala_Lumpur_floods'),
  ('Q796498', 'Third Indochina War', 'The Third Indochina War was a series of interconnected military conflicts among the various communist factions over strategic influence in mainland Southeast Asia after communist victory in South Vietnam, Laos, and Cambodia in 1975. The conflict primarily started due to continued raids and incursions by the Khmer Rouge into Vietnamese territory that they sought to retake.', 1975, 5, 1, 1991, 10, 23, 'day', '1 May 1975 – 23 October 1991', 53, 'https://en.wikipedia.org/wiki/Third_Indochina_War'),
  ('Q1467946', 'Malaysian Airline System Flight 653', 'Malaysian Airline System Flight 653 was a scheduled domestic flight from Penang to Kuala Lumpur in Malaysia, operated by Malaysian Airline System (MAS). On the evening of 4 December 1977, the Boeing 737-200 aircraft flying the service crashed at Tanjung Kupang, Johor, Malaysia, while purportedly being diverted by hijackers to Singapore.', 1977, 12, 4, NULL, NULL, NULL, 'day', '4 December 1977', 57, 'https://en.wikipedia.org/wiki/Malaysian_Airline_System_Flight_653'),
  ('Q6156492', 'Japan Airlines Flight 715', 'Japan Air Lines Flight 715 was a regular scheduled flight that crashed on approach to Subang Airport in Malaysia on 27 September 1977. The aircraft was a McDonnell Douglas DC-8, registration JA8051, on a flight from Haneda Airport in Tokyo, to Singapore, with stopovers at Hong Kong, and Subang Airport, Malaysia.', 1977, 9, 27, NULL, NULL, NULL, 'day', '27 September 1977', 47, 'https://en.wikipedia.org/wiki/Japan_Air_Lines_Flight_715'),
  ('Q7258363', 'Pudu Prison siege', 'Jimmy Chua Chap Seng (蔡捷成, 28 August 1947 – 10 October 1989), nicknamed Hokkien Chai, was a Singaporean criminal and former police officer who was infamous for masterminding the 1986 Pudu Prison hostage incident. Chua, who allegedly committed the murder of a police officer and several firearm offences in Malaysia, was detained at Pudu Prison when he and five other inmates decided to orchestrate a prison escape by taking two members of the prison staff hostage for six days.', 1986, 10, 22, 1986, 10, 22, 'day', '22 October 1986', 30, 'https://en.wikipedia.org/wiki/Jimmy_Chua_Chap_Seng'),
  ('Q5463543', 'Flying Tiger Line Flight 66', 'Flying Tiger Line Flight 066 was a scheduled international cargo flight from Changi Airport to Kai Tak Airport via a stopover at Kuala Lumpur International Airport. On 19 February 1989, the FedEx-owned Boeing 747-249F-SCD crashed while on its final approach.', 1989, 2, 19, NULL, NULL, NULL, 'day', '19 February 1989', 45, 'https://en.wikipedia.org/wiki/Flying_Tiger_Line_Flight_066'),
  ('Q20452334', 'Peace Agreement of Hat Yai 1989', 'The Hat Yai Peace Agreement marked the end of the Communist insurgency in Malaysia (1968–1989). It was signed and ratified by the Malayan Communist Party (MCP), and the Malaysian and Thailand governments at the Lee Gardens Hotel in Hat Yai, Thailand, on 2 December 1989.', 1989, 12, 2, NULL, NULL, NULL, 'day', '2 December 1989', 30, 'https://en.wikipedia.org/wiki/Hat_Yai_Peace_Agreement'),
  ('Q15911326', 'Malaysia Airlines Flight 2133', 'Malaysia Airlines Flight 2133 (MH2133/MAS2133) was a scheduled domestic passenger flight from Kota Kinabalu to Tawau, operated by Malaysia''s flag carrier Malaysia Airlines. On 15 September 1995, the Fokker 50 carrying 53 people overran the runway, continuing into a shanty town after the pilots failed to stop the aircraft while landing in Tawau, killing 32 of the 49 passengers and 2 of the 4 crew on board.', 1995, 9, 15, NULL, NULL, NULL, 'day', '15 September 1995', 50, 'https://en.wikipedia.org/wiki/Malaysia_Airlines_Flight_2133'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q4607654', '2006–07 Southeast Asian floods', 'The 2006–2007 Southeast Asian floods were a series of floods that mostly affected Malaysia from 18 December 2006 to 13 January 2007. The floods were caused by above average rainfall, which was attributed to Typhoon Utor (2006) which had hit the Philippines and Vietnam a few days earlier.', 2006, 12, 18, NULL, NULL, NULL, 'day', '18 December 2006', 39, 'https://en.wikipedia.org/wiki/2006%E2%80%932007_Southeast_Asian_floods'),
  ('Q2643482', '2010 floods in Thailand and north Malaysia', 'A series of flash floods hit different areas of Thailand and Malaysia in 2010. Separate but related floods began in Northeast and Central Thailand (per the six-region definition) in early October due to abnormally late monsoon moisture over the Bay of Bengal, overflowed the Chao Phraya where the rivers meet, and affected Bangkok, and in the South were triggered by a tropical depression about two weeks later, and were later aggravated by related La Niña monsoon rains.', 2010, 10, NULL, NULL, NULL, NULL, 'month', 'October 2010', 37, 'https://en.wikipedia.org/wiki/2010_Thailand%E2%80%93Malaysia_floods'),
  ('Q4846093', '2013 Lahad Datu standoff', 'The 2013 Lahad Datu standoff, also known as the Lahad Datu incursion or Operation Daulat (Malay: Operasi Daulat), was a military conflict in Lahad Datu, Malaysia. The conflict began on 11 February, when 235 militants arrived in Lahad Datu by boat, and ended on 24 March.', 2013, 2, 11, NULL, NULL, NULL, 'day', '11 February 2013', 50, 'https://en.wikipedia.org/wiki/2013_Lahad_Datu_standoff'),
  ('Q20051451', '2015 Sabah earthquake', 'The 2015 Sabah earthquake (Malay: Gempa Bumi Sabah 2015) struck Ranau, Sabah, Malaysia with a moment magnitude of 6.0 on 5 June, which lasted for 30 seconds. The earthquake was the strongest to affect Malaysia since the 1976 Sabah earthquake.', 2015, 6, 4, NULL, NULL, NULL, 'day', '4 June 2015', 48, 'https://en.wikipedia.org/wiki/2015_Sabah_earthquake'),
  ('Q28798841', 'assassination of Kim Jong-nam', 'On 13 February 2017, Kim Jong-nam, the older half-brother of the North Korean leader Kim Jong Un, was assassinated at Kuala Lumpur International Airport in Malaysia. He had been living abroad since his exile from North Korea in 2003.', 2017, 2, 13, NULL, NULL, NULL, 'day', '13 February 2017', 52, 'https://en.wikipedia.org/wiki/Assassination_of_Kim_Jong-nam'),
  ('Q66798078', '2019 Kuala Koh measles outbreak', 'The 2019 Kuala Koh measles outbreak was a measles outbreak that occurred among the Orang Asli sub-group of Batek people in Kuala Koh Village in the state of Kelantan, Malaysia, from May until July. Following the sudden deaths of several villagers, the disease became a mystery among the villagers and public for nearly a month until it was identified by the Malaysian Health Ministry in mid-June as measles.', 2019, 5, 2, 2019, 7, 8, 'day', '2 May 2019 – 8 July 2019', 30, 'https://en.wikipedia.org/wiki/2019_Kuala_Koh_measles_outbreak'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q104764792', '2020–21 Malaysian floods', '2020–2021 Malaysian floods was an event when several states in Malaysia were flooded in late 2020 and early 2021. Floods caused about tens of thousands of people to be evacuated to evacuation centers.', 2020, NULL, NULL, NULL, NULL, NULL, 'year', '2020', 37, 'https://en.wikipedia.org/wiki/2020%E2%80%932021_Malaysian_floods'),
  ('Q110184654', 'December 2021 Malaysian floods', 'On 16 December 2021, a tropical depression made landfall on the eastern coast of Peninsular Malaysia, bringing torrential downpours throughout the peninsula for three days. The resulting floods affected eight states across the peninsula, and left at least 54 dead and 2 missing.', 2021, 12, 17, NULL, NULL, NULL, 'day', '17 December 2021', 53, 'https://en.wikipedia.org/wiki/2021%E2%80%932022_Malaysian_floods');
